"2. A  guided the three wise men, who were kings, to Bethlehem.",
"3.  was afraid when he heard of the birth of a new King.",
"4. Herod told the wise men to come and tell him the whereabouts of the new born king, because he wanted to  the child.",
"5. An angel told 5  to take the Mother and the Child to 6.",
"1 6",
"5 3",
"The three wise men followed a the star to Bethlehem and presented fold, frankincense and myrrh to the new born king, Jesus Christ."
