"2. Why was Herod the king afraid when the three wise men told him that they came to worship the new born king?",
"3. What did Herod tell the wise men to do?",
"4. What did Herod do when he learned that the wise men did not return to him?",
"5. Where did the Virgin Mary, Jesus Christ and Joseph go to escape from Herod?",
"The Virgin Mary, Jesus Christ and Joseph stayed in Egypt for three and half years and returned to Jerusalem. The lived in a city called Galilee. Jesus Christ grew up obeying His mother, and Joseph. When He became 30 years old, he went to the Jordan River to be baptized. There was a man called John who was preaching Repentance, and baptizing the people in the Jordan River. He was the son of the priest, Zachariah, and Elizabeth. He told the people, \"I indeed baptize you with water for repentance, but He who is coming after me is mightier than I, whose sandals I am not worthy to carry, He will baptize you with the Holy Spirit and fire.\" Then Jesus came from Galilee to the Jordan River to be baptized by John. But John tried to prevent Him saying he is the one who needed to be baptized by Jesus. But Jesus insisted that it is the right thing to do, and John baptized Jesus Christ. John became know us John the Baptist because he baptized Jesus Christ. When Jesus came from the water:",
"1. The heavens were opened and the Spirit of God descended upon Jesus Christ like a dove.",
"2. A voice came from heaven saying, \"This is My beloved Son, in Whom I am well pleased.\" Immediately after He was baptized, Jesus fasted for 40 days and 40 nights before He started teaching the people about the Kingdom of Heaven.",
"Hore Eyesus Hore Eyesus (2) Em-Gelila (3) habe Yohannes (2)",
"Questions: Fill in the puzzle the answers for the blank spaces.",
