"2. Jesus Christ went to the  river to be baptized.",
"3.  baptized Jesus Christ in the Jordan River.",
"4. The Holy Spirit descended upon Jesus like a .",
"5. After Jesus baptism, a voice came from heaven saying: This is my beloved  in whom I am well pleased.",
