"Once upon a time, when Jesus entered a small village, ten lepers met him standing far away from him. Do you know what lepers are? ... Lepers are people who have a disease called leprosy. It is a skin disease. It was considered a sign of sin at the time, and those who had this disease were separated from the society. People used to avoid them because of this disease and they were not allowed to mix themselves with other people. That is why they were standing far away from other people as Jesus Christ entered a small village. When they saw Jesus Christ, they raised their voice and said, \"Jesus, Master, have mercy on us\". Jesus Christ then said to them, \"Go and show yourselves to priests.\" As they went to show themselves to priests, they were healed from their leprosy, and they all had beautiful skin again. One of them, when he saw that he was healed, returned back and glorified God. He fell on his face at the feet of Jesus Christ and thanked Him. Then Jesus Christ said, were there not ten that were healed? But only one of them came back to say thank you? He said to the one who came to glorify Him, go your way, your faith has made you well.",
