"There was a woman who had been bleeding for 12 years, and suffering a great deal of pain. She had seen many doctors seeking to be healed, but no one could cure here. Her condition was getting worse by the day. Once upon a time, Jesus Christ was passing by where she was. There were many people who were following Him, and they were pressing around Him. When this woman heard that Jesus Christ was passing by, She thought: \"If I just touch His Clothes, I will be healed.\" So, she came behind Him in the middle of the crowd and touched His Clothes. Her bleeding stopped immediately, and she was free of her suffering. Jesus turned back and asked who touched Him; but His disciples replied that the crowd was pressing against Him. But He said some one had touched Him, and looked around again. The woman came and fell at His feet in fear, and spoke of the miracle that was done for her when she touched His clothes. Jesus said to her: \" Daughter, your faith has healed you. Go in peace and be freed from your suffering.\"",
