"The morning after Jesus' triumphal entry into Jerusalem, He was hungry and came to a fig tree, to get some fruit from it. But there was no fruit on the tree. It had only leaves, and no fruit. Jesus then said: \"Let no fruit ever grow on you from now on.\" And the fig tree withered immediately. Jesus disciples were amazed to see the fig tree wither so soon, and said to one another: \"How soon is the fig tree withered away?\" Jesus then answered and told them not to marvel, for if they have faith, not only could they do what he did to the fig tree, but if they tell the mountain to move and go into the see, it shall be done for them. He said to them: \"All things whatsoever you shall ask in prayer, believing, you shall receive.\"",
